const dealStatus = d => { if (d.srv) return d.srv.status; const t = d.dates; if (t.cancelled) return 'cancelled'; if (t.declined) return 'declined'; if (t.agreed) return 'agreed'; if (t.reminded) return 'offer_follow_up'; if (t.offerSent) return 'offer_sent'; return 'draft_offer'; };
// Live payments carry received / outstanding / fully paid from payments_with_balance.
// d is the payment's deal: unpaid payments on a cancelled deal show as 'cancelled',
// matching money_summary, which leaves them out of owed / overdue / waiting.
const calc = (p, d) => {
  const cur = d.currency, gone = !!(d.dates && d.dates.cancelled);
  const rec = p.srv ? p.srv.received : p.receipts.reduce((a, r) => a + r.amount, 0);
  const rem = p.srv ? p.srv.outstanding : Math.max(0, p.amount - rec), paid = p.srv ? p.srv.fullyPaid : rec >= p.amount;
  const st = p.writtenOffAt ? 'wo' : paid ? 'paid' : gone ? 'cancelled' : p.disputedAt ? 'disputed' : p.dueDate && p.dueDate < TODAY ? 'overdue' : 'waiting';
  const f = n => money(cur, n);
  const prog = paid ? 'Fully paid' : gone ? (rec > 0 ? `${f(rec)} received before the deal was cancelled` : 'Not collected · the deal was cancelled') : rec > 0 ? `${f(rec)} of ${f(p.amount)} received · ${f(rem)} remaining` : `${f(p.amount)} due · nothing received yet`;
  const meta = {
    overdue: { l: 'Overdue · was due ' + fds(p.dueDate), short: 'Overdue', fg: '#B42318', ic: 'alert-circle', bar: '#7E65D6' },
    waiting: { l: 'Due ' + fds(p.dueDate), short: 'Waiting to be paid', fg: '#5E5E66', ic: 'clock', bar: '#7E65D6' },
    disputed: { l: 'Disputed since ' + fd(p.disputedAt), short: 'Disputed', fg: '#9A4A0C', ic: 'shield-alert', bar: '#D9963F' },
    wo: { l: 'Written off', short: 'Written off', fg: '#5E5E66', ic: 'ban', bar: '#C9CBD0' },
    cancelled: { l: 'Deal cancelled', short: 'Deal cancelled', fg: '#5E5E66', ic: 'x-circle', bar: '#C9CBD0' },
    paid: { l: 'Fully paid', short: 'Fully paid', fg: '#1F6F43', ic: 'check-circle-2', bar: '#2E9E5B' }
  }[st];
  return { rec, rem, paid, st, prog, pct: Math.min(100, p.amount ? rec / p.amount * 100 : 0), ...meta };
};
